  function ensureBrain(clientId){let b=app().brain.find(x=>x.clientId===clientId);if(!b){b={clientId,text:'',routine:'',backstage:'',stories:'',entries:[]};app().brain.push(b)}for(const [key,legacy,title]of [['routineItems','routine','Anotacoes anteriores'],['backstageItems','backstage','Anotacoes anteriores'],['storyItems','stories','Historia anterior']])if(!Array.isArray(b[key]))b[key]=b[legacy]?[{id:'legacy-'+key,title,text:b[legacy],createdAt:''}]:[];return b}
  function buildKnowledgeSummary(c,b){const p=c?.profile||{},o=c?.products?.[0]||{},rows=[];const add=(label,value)=>{const v=String(value||'').trim();if(v)rows.push(label+': '+v)};add('Perfil',c?.name);add('Instagram',p.instagramHandle&&('@'+String(p.instagramHandle).replace(/^@/,'')));add('Atuacao',p.niche);add('Publico',p.audience);add('Tom de voz',p.voice);add('Oferta',o.name||p.productName);add('Promessa',o.promise||p.productPromise);add('Problema que resolve',o.problem||p.productProblem);add('Entrega',o.delivery||p.productDelivery);add('Objecoes',o.objections||p.productObjections);add('Prova autorizada',o.proof||p.productProof);add('Chamada para acao',o.cta||p.productCta);for(const[k,label]of [['subniche','Subnicho'],['editorialThemes','Temas editoriais'],['audiencePain','Situacoes da audiencia'],['originStory','Historia de origem'],['brandBeliefs','Cren?as e valores'],['audienceTransformation','Transformacao desejada'],['contentMustHave','Conteudos permitidos ou importantes'],['contentMustAvoid','Conteudos a evitar'],['contentTolerance','Tom e abordagem tolerados'],['contentCtaRules','Regras de chamada e prova']])add(label,p[k]);if(b?.text&&b.text!==b.knowledgeSummary)add('Conhecimento anterior',b.text);for(const[k,label]of [['routineItems','Rotina'],['backstageItems','Bastidores'],['storyItems','Historias']])for(const item of (b?.[k]||[]).slice(-20))add(label+' - '+(item.title||'Sem tema'),String(item.text||'').slice(0,360));for(const note of b?.entries||[])add('Nota anterior',note);const assets=(c?.assets||[]).filter(a=>a.text).map(a=>a.name);if(assets.length)add('Materiais lidos',assets.join(', '));return rows.join('\n').slice(0,16000)||'Ainda nao ha informacoes suficientes neste perfil. Complete o perfil e registre rotina, bastidores ou historias para a Devil conhecer a pessoa.'}
